use std::collections::HashMap;

#[derive(Debug, Clone, Copy)]
enum Player {
    X,
    O,
}

#[derive(Debug)]
struct Board {
    board: [[Player; 4]; 4],
}

impl Board {
    fn new() -> Self {
        Board {
            board: [[Player::X, Player::O, Player::X, Player::O],
                    [Player::O, Player::X, Player::O, Player::X],
                    [Player::X, Player::O, Player::X, Player::O],
                    [Player::O, Player::X, Player::O, Player::X]],
        }
    }

    fn is_full(&self) -> bool {
        for row in self.board.iter() {
            for &player in row.iter() {
                if player == Player::X || player == Player::O {
                    return false;
                }
            }
        }
        true
    }

    fn is_winner(&self, player: Player) -> bool {
        // Check rows and columns
        for i in 0..4 {
            if self.board[i][0] == player && self.board[i][1] == player && self.board[i][2] == player && self.board[i][3] == player {
                return true;
            }
            if self.board[0][i] == player && self.board[1][i] == player && self.board[2][i] == player && self.board[3][i] == player {
                return true;
            }
        }

        // Check diagonals
        if self.board[0][0] == player && self.board[1][1] == player && self.board[2][2] == player && self.board[3][3] == player {
            return true;
        }
        if self.board[0][3] == player && self.board[1][2] == player && self.board[2][1] == player && self.board[3][0] == player {
            return true;
        }

        false
    }

    fn make_move(&mut self, row: usize, col: usize, player: Player) {
        if row < 4 && col < 4 && self.board[row][col] == Player::X || self.board[row][col] == Player::O {
            println!("Invalid move. Try again.");
            return;
        }

        self.board[row][col] = player;
    }

    fn print_board(&self) {
        for row in self.board.iter() {
            for &player in row.iter() {
                match player {
                    Player::X => print!("X "),
                    Player::O => print!("O "),
                    _ => print!("  "),
                }
            }
            println!();
        }
    }
}

fn main() {
    let mut board = Board::new();
    let mut current_player = Player::X;

    loop {
        board.print_board();
        println!("Player {}'s turn. Enter row and column (0-3):", current_player);
        let mut input = String::new();
        std::io::stdin().read_line(&mut input).expect("Failed to read line");
