            .split_whitespace()
            .map(|s| s.parse().expect("Please type a number!"))
            .collect();

        if input.len() != 2 {
            println!("Invalid input. Please enter two numbers.");
            continue;
        }

        let row = input[0];
        let col = input[1];

        if board.board[row][col] != Player::X && board.board[row][col] != Player::O {
            board.make_move(row, col, current_player);
            if board.is_winner(current_player) {
