                println!("Player {} wins!", current_player);
                break;
            }
            if board.is_full() {
                board.print_board();
                println!("It's a draw!");
                break;
            }
            current_player = match current_player {
                Player::X => Player::O,
                Player::O => Player::X,
            };
        } else {
            println!("Invalid move. Try again.");
        }
    }
}
